CREATE TABLE "public"."clients" (
  "id"               bigint                      GENERATED BY DEFAULT AS IDENTITY (SEQUENCE NAME "public"."Clients_id_seq") NOT NULL,
  "created_at"       timestamp with time zone    NOT NULL DEFAULT now(),
  "user_telegram_id" character varying,
  "first_name"       character varying,
  "last_name"        character varying,
  "last_message_at"  timestamp without time zone NOT NULL,
  CONSTRAINT "Clients_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."clients"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."messages" (
  "id"                bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "created_at"        timestamp with time zone NOT NULL DEFAULT now(),
  "author"            character varying,
  "body"              text,
  "messenger_user_id" character varying,
  "messenger_type"    character varying,
  "client_id"         bigint,
  CONSTRAINT "messages_pkey" PRIMARY KEY (id)
);

ALTER TABLE "public"."messages"
  ENABLE ROW LEVEL SECURITY;

ALTER TABLE "public"."messages"
  ADD CONSTRAINT "messages_client_id_fkey" FOREIGN KEY (client_id) REFERENCES public.clients(id);

CREATE UNIQUE INDEX clients_user_telegram_id_uidx ON public.clients USING btree (user_telegram_id);

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."clients" TO "anon", "authenticated", "postgres", "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."messages" TO "anon", "authenticated", "postgres", "service_role";

